SELECT customers.id, customers.is_active, t.monthly_fee_count, t.pct_basic FROM customers INNER JOIN (SELECT customer_id, COUNT(monthly_fee) AS monthly_fee_count, ROUND((100 * SUM(CASE WHEN plan = 'basic' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_basic FROM subscriptions GROUP BY customer_id) t ON customers.id = t.customer_id WHERE t.monthly_fee_count > 5 ORDER BY id DESC, monthly_fee_count DESC
